appearances.css:
.app{display:flex;flex-wrap:wrap;align-content:flex-start;gap:4px;padding:6px;font-size:9px;border-radius:4px;--pk-wave-h:64px}
.app>*{min-width:0}
button,select,input{padding:2px 5px;font-size:9px;border-radius:3px}
.row{margin:0;gap:3px;flex:1 1 100%;align-items:center}
.row button{height:24px;padding:2px 4px;font-size:8.5px}
.row .control{display:flex;flex-direction:row;align-items:center;gap:3px;border:0;padding:0;flex:0 0 auto}
.row .control>span{font-size:7.5px;letter-spacing:-.03em}
.row select{height:24px}
.app>input[type=file]{flex:1 1 100%;width:auto;height:24px;padding:0 3px;font-size:9px;line-height:20px}
input[type=file]::file-selector-button{font:inherit;padding:1px 5px;margin:0 4px 0 0;border-radius:3px}
canvas{flex:1 1 100%;width:100%;border-radius:3px}
.pads{flex:1 1 100%;grid-template-columns:repeat(8,minmax(0,1fr));gap:3px}
.pads button{min-height:26px;padding:1px 3px;font-size:8px;line-height:1.2;white-space:normal;overflow:hidden;text-align:left;border-radius:3px}
.grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:4px 0;align-content:start;padding:3px 4px 4px;border:1px solid var(--line,#39424e);border-radius:3px;flex:1 1 100%}
.grid .control{display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-content:start;gap:0;border:0;padding:0;min-width:0}
.grid .control>span:not(.kn){order:3;font-size:7px;line-height:1.1;text-align:center;max-width:100%;letter-spacing:-.05em;overflow-wrap:anywhere;padding:0 2px}
.grid output{order:2;font:8px/1.1 monospace;text-align:center;white-space:nowrap}
.grid .kn{order:1;width:28px!important;height:28px!important;justify-self:center!important}
.grid .kn svg{width:100%;height:100%}
.grid .control:has(select) select{order:1;width:54px;height:24px;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none;padding:2px 0}
h3{display:none}
.row:nth-of-type(5){flex:1 1 100%}
.row:nth-of-type(6){flex:1 1 100%}
.row:nth-of-type(6) input[type=file]{flex:1 1 110px;width:auto;height:24px;padding:0 3px;font-size:8.5px;line-height:20px}
p{margin:0;font-size:8px;line-height:1.2;flex:1 1 100%}
